def gen(rng):
    def fmt(c, ops):
        return f"{len(ops)} {c}\n" + '\n'.join(ops)

    tests = [
        fmt(1, ['list']),
        fmt(1, ['open a', 'list']),
        fmt(3, ['open a', 'open b', 'open c', 'open a', 'open d', 'list', 'open e', 'list']),
        fmt(1, ['open x', 'open x', 'open y', 'list']),
        fmt(2, ['open a', 'open b', 'open a', 'open c', 'open b', 'list']),
        fmt(5, ['open a', 'open b', 'list', 'open a', 'list']),
        fmt(10, [f"open t{i}" for i in range(12)] + ['list']),
    ]
    for _ in range(60):
        c = rng.randint(1, 5)
        pool = [f"t{i}" for i in range(rng.randint(1, 9))]
        ops = []
        for _ in range(rng.randint(1, 30)):
            ops.append('list' if rng.random() < 0.2 else f"open {rng.choice(pool)}")
        tests.append(fmt(c, ops))
    n = 100000

    def big(c, pool_size, n_list):
        ops = [f"open t{rng.randrange(pool_size)}" for _ in range(n)]
        for p in rng.sample(range(n), n_list):
            ops[p] = 'list'
        return fmt(c, ops)

    tests.append(big(50000, 100000, 6))
    tests.append(big(10, 15, 3000))
    tests.append(big(100000, 100000, 3))
    tests.append(big(30000, 40000, 6))
    return tests
